/* assets_win.h — Windows asset store over the DLL's RCDATA resources.
 *
 * The engine reads the data pack through stdio_asset.c's fopen/fread shadow,
 * which resolves paths via sf_asset_lookup(). On Windows the pack ships as
 * RCDATA resources (pack.rc, generated by tools/gen_assets.py --win) and this
 * module serves them. DllMain passes the module handle in.
 */
#pragma once

#include <windows.h>

/* Record the DLL instance so FindResource can find the pack resources. */
void sf_asset_set_hinstance(HINSTANCE hinst);